# BAD: client fully controls history
def handle_workflow(req):
    history = req.get("history", [])   # attacker-supplied!
    context = build_context(req["prompt"], history)
    return orchestrator.run(context)

# GOOD: history is server-side and authenticated
def handle_workflow(req, session):
    history = session.load_verified_history()   # server-owned
    context = build_context(req["prompt"], history)
    return orchestrator.run(context)
